1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.time.LocalDate;
4	
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	
7	/**
8	 * Rejects a create request once the daily signup limit has been reached.
9	 *
10	 * <p>Runs after {@link CheckOwnerCityCapacity} and before {@link BuildOwner}. The clinic accepts at
11	 * most 100 new owners per day: when 100 or more owners already carry today's registration date, the
12	 * next create is refused. A match throws {@link OwnerDailyLimitReachedException}, handled as a 429
13	 * Too Many Requests.
14	 */
15	public class CheckOwnerDailyLimit {
16	
17	    /** Maximum number of owners that may be created on a single day; the next owner is rejected. */
18	    private static final int DAILY_LIMIT = 100;
19	
20	    public void service(OwnerRepository ownerRepository)
21	            throws OwnerDailyLimitReachedException {
22	        LocalDate today = LocalDate.now();
23	        long createdToday = ownerRepository.findAll().stream()
24	                .filter(existing -> today.equals(existing.getRegistrationDate()))
25	                .count();
26	        if (createdToday >= DAILY_LIMIT) {
27	            throw new OwnerDailyLimitReachedException(today);
28	        }
29	    }
30	}
