309				}
310				int d = c - '0';
311				if (dbl) {
312					d *= 2;
313					if (d > 9) {
314						d -= 9;
315					}
316				}
317				sum += d;
318				dbl = !dbl;
319			}
320			return (10 - (sum % 10)) % 10;
