public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
        throws OwnerDailyLimitReachedException {
    // Count against the business day this owner will actually be registered on: the effective
    // date (supplied or defaulted to today), rolled forward off a weekend. Stored registration
    // dates are already adjusted, so this buckets owners per adjusted business day.
    LocalDate effective = request.getRegistrationDate() != null
            ? request.getRegistrationDate() : LocalDate.now();
    LocalDate businessDay = BusinessDays.toBusinessDay(effective);
    long createdToday = ownerRepository.findAll().stream()
            .filter(existing -> businessDay.equals(existing.getRegistrationDate()))
            .count();
    if (createdToday >= DAILY_LIMIT) {
        throw new OwnerDailyLimitReachedException(businessDay);
    }
}

